package fraymus.workspace;
import org.json.*;

/** Compact actual trace presentation; complete pixel/run exports stay separate. */
final class ObservationReport {
    static JSONObject data(JSONObject run){var rows=new JSONArray();for(Object raw:run.getJSONArray("trace")){var f=(JSONObject)raw;for(Object item:f.getJSONArray("objects")){var o=(JSONObject)item;var e=WorldFrames.copy(o.getJSONObject("estimate"));e.put("bodyId",o.getString("bodyId")).put("ordinal",f.getInt("ordinal")).put("imageSha256",f.getString("imageSha256")).put("trackerStatus",o.getJSONObject("tracker").getString("status"));rows.put(e);}}return new JSONObject().put("id",run.getString("id")).put("status",run.getString("status")).put("nativeBinding",run.getJSONObject("nativeBinding")).put("rows",rows);}
    static JSONObject build(JSONObject run){String json=data(run).toString().replace("<","\\u003c");String html="""
        <!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Observed world · edition036</title>
        <style>body{background:#101b26;color:#edf4fa;font:16px system-ui;margin:0;padding:24px;max-width:1100px}h1{font-size:26px}p{line-height:1.6;color:#b9ccda}select,button{font:inherit;background:#243c50;color:white;border:1px solid #56738b;padding:8px;border-radius:7px}canvas{width:100%;background:#152739;border-radius:12px;margin:14px 0}table{border-collapse:collapse;width:100%}td,th{border-bottom:1px solid #375169;padding:8px;text-align:left;white-space:nowrap}.scroll{overflow:auto}code{overflow-wrap:anywhere}#legend{color:#78dfbf}</style>
        <h1>Observe → predict → compare → update</h1><p>Original Java tracking and covariance-filter results, attached to the same persistent world and body identities. Native verified physics is unchanged. Positions use normalized image coordinates; time uses the declared source-frame/sample index. Depth, physical scale and capture FPS are unknown. Model covariance is not calibrated confidence.</p>
        <p id="identity"></p><label>Actual metric <select id="metric"><option value="x">Horizontal position</option><option value="y">Vertical position</option><option value="innovation">Prediction discrepancy</option><option value="positionSigma">Model uncertainty</option><option value="velocity">Horizontal velocity / frame index</option></select></label><button id="reset">Reset chart</button><canvas id="chart" width="1000" height="310" aria-label="Actual prediction and observation chart"></canvas><p id="legend"></p><p id="summary"></p><div class="scroll"><table><thead><tr><th>Frame index</th><th>Stable body ID</th><th>Tracker</th><th>Update</th><th>Predicted X</th><th>Estimated X</th><th>Discrepancy</th><th>Model σ</th></tr></thead><tbody id="rows"></tbody></table></div>
        <script id="evidence" type="application/json">__JSON__</script><script>
        const data=JSON.parse(document.getElementById('evidence').textContent),$=id=>document.getElementById(id);window.observationEvidence=data;
        $('identity').textContent='World '+data.nativeBinding.worldId+' · native revision '+data.nativeBinding.expectedRevision+' · observation run '+data.id+' · '+data.status;
        let accepted=0;for(const r of data.rows){if(r.accepted)accepted++;const tr=document.createElement('tr');for(const v of [r.time,r.bodyId,r.trackerStatus,r.status,r.predicted[0].toFixed(5),r.position[0].toFixed(5),r.innovation?.toFixed(5)??'missing',r.positionSigma.toFixed(5)]){const td=document.createElement('td');td.textContent=v;tr.append(td);}$('rows').append(tr);}
        $('summary').textContent=data.rows.length+' actual object/frame results · '+accepted+' accepted measurements · '+(data.rows.length-accepted)+' predicted/rejected updates';
        function draw(){const mode=$('metric').value,series=[],bodies=[...new Set(data.rows.map(r=>r.bodyId))];for(const body of bodies){const rows=data.rows.filter(r=>r.bodyId===body);if(mode==='x'||mode==='y'){let k=mode==='x'?0:1;for(const [key,color]of [['predicted','#f3b565'],['measurement','#6caeff'],['position','#78dfbf']])series.push({body,key,color,points:rows.filter(r=>r[key]).map(r=>[r.time,r[key][k]])});}else series.push({body,key:mode,color:'#78dfbf',points:rows.filter(r=>mode==='velocity'||Number.isFinite(r[mode])).map(r=>[r.time,mode==='velocity'?r.velocity[0]:r[mode]])});}window.observationChart={mode,series};$('chart').dataset.proof=JSON.stringify({mode,series});const c=$('chart'),ctx=c.getContext('2d'),all=series.flatMap(s=>s.points);ctx.clearRect(0,0,c.width,c.height);if(!all.length)return;const xs=all.map(p=>p[0]),ys=all.map(p=>p[1]),minX=Math.min(...xs),maxX=Math.max(...xs),minY=Math.min(...ys),maxY=Math.max(...ys);ctx.strokeStyle='#56738b';ctx.beginPath();ctx.moveTo(45,15);ctx.lineTo(45,275);ctx.lineTo(985,275);ctx.stroke();for(const s of series){ctx.strokeStyle=s.color;ctx.lineWidth=2;ctx.beginPath();s.points.forEach((p,i)=>{let x=45+940*(p[0]-minX)/Math.max(1,maxX-minX),y=270-245*(p[1]-minY)/Math.max(.00001,maxY-minY);if(i)ctx.lineTo(x,y);else ctx.moveTo(x,y);});ctx.stroke();}ctx.fillStyle='#d2e3f0';ctx.font='13px system-ui';ctx.fillText(minY.toFixed(4),4,260);ctx.fillText(maxY.toFixed(4),4,20);ctx.fillText('frame index '+minX+' → '+maxX,60,300);$('legend').textContent=(mode==='x'||mode==='y')?'Orange: prediction before measurement · Blue: actual pixel measurement · Green: updated estimate':'Every recorded result for '+mode+'; missing measurements remain explicitly absent';}
        $('metric').onchange=draw;$('reset').onclick=()=>{$('metric').value='x';draw();};draw();
        </script></html>
        """.replace("__JSON__",json);
        return new JSONObject().put("title","Observed world · "+run.getString("id").substring(0,8)).put("files",new JSONObject().put("index.html",html).put("observation-data.json",data(run).toString())).put("sources",new JSONArray().put(new JSONObject().put("runId",run.getString("id")).put("worldId",run.getJSONObject("nativeBinding").getString("worldId")).put("codeSha256",run.getString("codeSha256"))));
    }
}
